ProfileResult validate_catalog_profile(const OffsetProfile &profile) {
    if (auto result = validate_offset_profile(profile); !result) return result;
    for (const auto &spec : offset_catalog_specs()) {
        const auto it = profile.offsets.find(re::ReString(spec.key));
        if (!it)
            return {ProfileError::missing_key, "Missing catalog key: " + re::ReString(spec.key)};
        if ((**it).kind != spec.kind)
            return {ProfileError::kind_mismatch, "Wrong kind: " + re::ReString(spec.key)};
        if ((**it).module != spec.module)
            return {ProfileError::module_mismatch, "Wrong module: " + re::ReString(spec.key)};
    }
    return {};
}
